impl<A:ArtifactApp,M:SpaceMember+MemberFactory+'static> VcsArtifactApp<A,M>{
 pub(crate) fn capture_owned_tool_document(&self)->Result<ArtifactOwnedToolDocument<A>,Fault>{
  let generation=self.store.generation();
  let revision=self.store.content_revision();
  let parent=self.store.snapshot_read().map_err(Fault::from)?;
  let children=std::sync::Arc::new(ChildContentView::clone(&self.child_content_root));
  let child_generation=self.child_content_generation;
  if !parent.commit_authority_matches(generation,revision){
   return Err(Fault::new(FaultOrigin::Framework,FaultCode::new("interactive-job.document-publication-invariant"),"captured parent read differs from its synchronous child publication authority"))
  }
  Ok(ArtifactOwnedToolDocument{parent:Some(parent),children:Some(children),generation,child_generation,revision})
 }
}

